library(shiny)

merchantUI<-function(id){ns<-NS(id);tagList(tags$style(HTML(paste0("#",ns("wrap"),"{position:fixed;right:22px;bottom:94px;z-index:1039}#",ns("open"),"{width:58px;height:58px;border-radius:50%;font-size:24px;background:#31543b;color:#fff4cf;border:2px solid #d7b96d;box-shadow:0 5px 18px rgba(0,0,0,.35)}#",ns("badge"),"{position:absolute;right:-3px;top:-5px;background:#8f241d;color:white;border-radius:999px;min-width:22px;padding:2px 6px;text-align:center;font-weight:bold}"))),div(id=ns("wrap"),actionButton(ns("open"),"⚖",title="Merchants"),uiOutput(ns("badge"))))}

merchantServer<-function(id,state){moduleServer(id,function(input,output,session){`%||%`<-get("%||%",inherits=TRUE);poll<-reactiveTimer(3000,session);rev<-reactiveVal(0L);prompted<-reactiveVal(integer());active_id<-reactiveVal(NA_integer_);active_quote<-reactiveVal(NULL)
  cid<-reactive({x<-state$char_id;if(is.null(x)||!length(x)||is.na(x[[1]]))""else as.character(x[[1]])})
  invitations<-reactive({poll();rev();if(!nzchar(cid())||isTRUE(state$offline_mode))return(data.frame());get_pending_merchant_invitations(cid(),FALSE)})
  output$badge<-renderUI({n<-sum(invitations()$status=="pending");if(n>0)span(n)})
  merchant_choices<-function(){x<-invitations();if(!nrow(x))character()else setNames(as.character(x$merchant_id),paste0(x$name," · ",tools::toTitleCase(x$specialty)))}
  close_stale_shop<-function(message="That merchant has closed and is no longer trading."){active_quote(NULL);active_id(NA_integer_);session$userData$pending_merchant_id<-NULL;removeModal();rev(rev()+1L);showNotification(message,type="warning",duration=8)}
  open_shop<-function(mid){mid<-suppressWarnings(as.integer(mid));bundle<-get_merchant_bundle(mid);if(is.null(bundle)||!identical(as.character(bundle$merchant$status[[1L]]),"open"))return(close_stale_shop());active_id(mid);mark_merchant_invitation(mid,cid(),"opened");session$userData$pending_merchant_id<-mid;rev(rev()+1L);showModal(modalDialog(size="l",title=paste0(bundle$merchant$name[[1L]]," — ",tools::toTitleCase(bundle$merchant$specialty[[1L]])," merchant"),uiOutput(session$ns("shop_body")),footer=tagList(actionButton(session$ns("leave_shop"),"Leave merchant",class="btn btn-default"))))}
  output$shop_body<-renderUI({rev();mid<-active_id();if(is.na(mid))return(NULL);b<-get_merchant_bundle(mid);if(is.null(b))return(p("Merchant closed."));m<-b$merchant;s<-b$stock;stock_choices<-if(nrow(s))setNames(as.character(s$id),vapply(seq_len(nrow(s)),function(i){item<-enemy_db_json(s$item_json[[i]],list());meta<-item$meta%||%list();animal_stats<-if(identical(item$type,"animal"))paste0(" · ",meta$species%||%"Animal"," · Speed ",meta$speed%||%30," · AC ",meta$armour_class%||%10," · HP ",meta$max_hp%||%5," · ",if(isTRUE(meta$mountable))"Mountable"else"Unmountable")else"";paste0(item$name%||%"Item"," · ",s$base_value[[i]],"g base · qty ",s$quantity[[i]],animal_stats)},character(1)))else character();char<-validate_character(state$char);inv<-inventory_normalize(char$inventory$items);if(nrow(inv))inv<-inv[!as.logical(inv$equipped%||%FALSE),,drop=FALSE];sell_choices<-if(nrow(inv))setNames(inv$id,paste0(inv$name," · ",inv$value,"g base · qty ",inv$qty))else character();tagList(p(strong(tools::toTitleCase(m$temperament[[1L]]))," haggler · Merchant purse: ",m$gold[[1L]],"g · Your purse: ",char$inventory$gold%||%0,"g"),p("Negotiate first. Nothing changes hands until you accept the quoted price. Rejecting a quote raises this merchant's next haggling DC by 2."),fluidRow(column(6,h4("Buy"),selectInput(session$ns("buy_stock"),"Stock",choices=stock_choices),actionButton(session$ns("buy"),"Haggle Purchase",class="btn btn-success")),column(6,h4("Sell"),selectInput(session$ns("sell_item"),"Your item",choices=sell_choices),actionButton(session$ns("sell"),"Haggle Sale",class="btn btn-primary"))))})
  observe({rev();if(is.na(active_id()))return();char<-validate_character(state$char);inv<-inventory_normalize(char$inventory$items);if(nrow(inv))inv<-inv[!as.logical(inv$equipped%||%FALSE),,drop=FALSE];item_choices<-if(nrow(inv))setNames(inv$id,paste0(inv$name," · ",inv$value,"g base · qty ",inv$qty))else character();stable<-get_character_stable(cid());animal_choices<-if(nrow(stable))setNames(paste0("animal:",stable$id),paste0("🐾 ",stable$name," · ",stable$gold_value,"g base · ",ifelse(stable$mountable,"Mountable","Unmountable")))else character();updateSelectInput(session,"sell_item",choices=c(item_choices,animal_choices))})
  negotiate<-function(direction){mid<-active_id();target<-if(direction=="buy")input$buy_stock else input$sell_item;if(is.na(mid)||is.null(target)||!nzchar(as.character(target)))return(showNotification("Choose an item first.",type="warning"));q<-create_merchant_quote(mid,cid(),direction,stock_id=if(direction=="buy")target else NULL,player_item_id=if(direction=="sell")target else NULL);if(merchant_action_failed(q)){msg<-merchant_error_message(q,"The merchant could not make a quote.");if(grepl("no longer open",msg,fixed=TRUE))return(close_stale_shop());return(showNotification(msg,type="error",duration=8))};active_quote(q);char_gold<-as.numeric(validate_character(state$char)$inventory$gold%||%0);bundle<-get_merchant_bundle(mid);if(is.null(bundle)||!identical(as.character(bundle$merchant$status[[1L]]),"open"))return(close_stale_shop());merchant_gold<-as.numeric(bundle$merchant$gold[[1L]]);can_afford<-if(direction=="buy")char_gold>=as.numeric(q$final_price[[1L]])else merchant_gold>=as.numeric(q$final_price[[1L]]);if(direction=="buy"&&as.integer(q$natural_roll[[1L]]%||%NA)==1L){if(!can_afford)return(showModal(modalDialog(title="Critical haggling failure",p("You rolled a natural 1. The merchant doubled the price to ",strong(paste0(q$final_price[[1L]]," gold"))," and tried to make the sale automatic, but you only have ",char_gold," gold. Nothing was bought."),footer=actionButton(session$ns("reject_quote"),"Leave Quote",class="btn btn-default"))));res<-merchant_trade(mid,cid(),quote_id=q$id[[1L]]);if(merchant_action_failed(res)){msg<-merchant_error_message(res);if(grepl("no longer open",msg,fixed=TRUE))return(close_stale_shop());return(showNotification(msg,type="error",duration=8))};state$char<-res$character;active_quote(NULL);rev(rev()+1L);showModal(modalDialog(title="Critical haggling failure — automatic purchase",p("You rolled a natural 1 on Persuasion. The merchant doubled the base price and the purchase was automatically approved."),p(strong(res$item_name)," cost ",strong(paste0(res$terms$price," gold"))," and has been added to your inventory."),footer=actionButton(session$ns("return_to_shop"),"Return to Merchant",class="btn btn-primary")));return()};showModal(modalDialog(title=if(direction=="buy")"Purchase quote"else"Sale quote",p(if(isTRUE(q$haggle_success[[1L]]))"Your haggling succeeded."else"The merchant held firm."),p(strong(q$item_name[[1L]])," · Roll ",q$haggle_roll[[1L]]," vs DC ",q$haggle_dc[[1L]]," · Quoted price: ",strong(paste0(q$final_price[[1L]]," gold"))),if(!can_afford)p(style="color:#9b241c;font-weight:bold",if(direction=="buy")paste0("You only have ",char_gold," gold.")else paste0("The merchant only has ",merchant_gold," gold.")),p("Declining makes the next attempt with this merchant harder."),footer=tagList(actionButton(session$ns("reject_quote"),"Decline Quote",class="btn btn-default"),actionButton(session$ns("accept_quote"),if(direction=="buy")"Confirm Purchase"else"Confirm Sale",class="btn btn-success",disabled=if(!can_afford)"disabled"else NULL))))}
  observeEvent(input$buy,negotiate("buy"),ignoreInit=TRUE);observeEvent(input$sell,negotiate("sell"),ignoreInit=TRUE)
  observeEvent(input$reject_quote,{q<-active_quote();if(!is.null(q))reject_merchant_quote(q$id[[1L]],cid());active_quote(NULL);removeModal();open_shop(active_id())},ignoreInit=TRUE)
  observeEvent(input$accept_quote,{q<-active_quote();if(is.null(q))return();res<-merchant_trade(active_id(),cid(),quote_id=q$id[[1L]]);if(merchant_action_failed(res)){msg<-merchant_error_message(res,"The trade could not be completed.");if(grepl("no longer open",msg,fixed=TRUE))return(close_stale_shop());return(showNotification(msg,type="error",duration=8))};state$char<-res$character;active_quote(NULL);rev(rev()+1L);removeModal();t<-res$terms;destination<-if(isTRUE(res$is_animal))" It is now in your Stables."else"";showNotification(paste0(if(res$direction=="buy")"Purchased "else"Sold ",res$item_name," for ",t$price," gold.",destination),type="message",duration=8);open_shop(active_id())},ignoreInit=TRUE)
  observeEvent(input$return_to_shop,{removeModal();open_shop(active_id())},ignoreInit=TRUE)
  observeEvent(input$leave_shop,{session$userData$pending_merchant_id<-NULL;removeModal()},ignoreInit=TRUE)
  observeEvent(input$open,{choices<-merchant_choices();if(!length(choices))return(showNotification("No merchant is currently trading with you.",type="message"));if(length(choices)==1)return(open_shop(unname(choices[[1L]])));showModal(modalDialog(title="Available merchants",selectInput(session$ns("merchant_choice"),"Merchant",choices=choices),footer=tagList(modalButton("Cancel"),actionButton(session$ns("choose_merchant"),"Visit",class="btn btn-success"))))},ignoreInit=TRUE)
  observeEvent(input$choose_merchant,{removeModal();open_shop(input$merchant_choice)},ignoreInit=TRUE)
  observe({invalidateLater(3000,session);if(!nzchar(cid())||isTRUE(state$offline_mode)||!is.null(session$userData$pending_merchant_id)||!is.null(session$userData$pending_trade_id)||!is.null(session$userData$pending_note_id)||!is.null(session$userData$pending_opportunity))return();fresh<-get_pending_merchant_invitations(cid(),TRUE);fresh<-fresh[!fresh$merchant_id%in%prompted(),,drop=FALSE];if(!nrow(fresh))return();r<-fresh[1,,drop=FALSE];prompted(unique(c(prompted(),r$merchant_id)));session$userData$pending_merchant_id<-as.integer(r$merchant_id[[1L]]);showModal(modalDialog(title=paste0(r$name[[1L]]," would like to trade"),p("A ",r$wealth_class[[1L]]," ",r$specialty[[1L]]," merchant with a ",r$temperament[[1L]]," haggling style has opened their wares."),footer=tagList(actionButton(session$ns("dismiss_invite"),"Not now"),actionButton(session$ns("accept_invite"),"View wares",class="btn btn-success"))))})
  observeEvent(input$accept_invite,{mid<-session$userData$pending_merchant_id;removeModal();open_shop(mid)},ignoreInit=TRUE)
  observeEvent(input$dismiss_invite,{session$userData$pending_merchant_id<-NULL;removeModal();rev(rev()+1L)},ignoreInit=TRUE)
})}
